page.css:
		[style]
			body {font-family: Verdana,helvetica; font-size: 10pt ; background: #fafafa; color: black; }
			li {font-family: Verdana,helvetica; font-size: 8pt }
			th {font-family: Verdana,helvetica; font-size: 8pt ; background: #3882c7; font-weight: normal; color: white}
			td.subtitle {font-family: Verdana,helvetica; background: #58A2E7; font-size: 8pt ; color: white}
			td.footer {font-family: Verdana,helvetica; background: #e0e0e0; font-size: 8pt ; color: #5050e2}
			td.summary {font-family: Verdana,helvetica; font-size: 8pt ; background: #d0d0d0; font-style: italic; color: black}
			td.total {verfont-family: Verdana,helvetica; font-size: 8pt; background: #58A2E7; font-weight: bold; color: white}
			td.tool {font-family: Verdana,helvetica; font-size: 8pt; background: white; color: black}
			td.alert {font-family: Verdana,helvetica; font-size: 8pt ; background: #FF0000; font-weight: bold; color: white}
			td {font-family: Verdana,helvetica; background: white; font-size: 8pt ; color: black;	border-bottom-width: 1px;
	border-top-style: solid;
	border-bottom-style: solid;
	border-top-color: #ffffff;
	border-bottom-color: #999999;
}
			h1 {font-family: Verdana,helvetica; font-size: 13pt ; color: black}
			h2 {font-family: Verdana,helvetica; font-size: 12pt ; color: black}
			h3 {font-family: Verdana,helvetica; font-size: 10pt ; color: #3A81C1; font-weight: bold }
			h4 {font-family: Verdana,helvetica; font-size: 10pt ; color: #3A81C1}
			h5 {font-family: Verdana,helvetica; font-size: 8pt ; color: #3A81C1}
			input {font-family: Verdana,helvetica; font-size: 8pt}
			input.tool {font-family: Verdana,helvetica; background: white;font-size: 8pt}
			input.navig {width:24px; font-family: Verdana,helvetica; background: white;font-size: 8pt}
			input.export {width:31px; font-family: Verdana,helvetica; background: white;font-size: 8pt}
			font {font-family: Verdana,helvetica; font-size: 10pt ; color: #140181}
			a {text-decoration: none; font-family: Verdana,helvetica; font-size: 10pt ; background:#f0f0f0; color: #3882c7}
			a:hover {text-decoration: underlined; font-family: Verdana,helvetica; font-size: 10pt ; background:white; color: #3882c7}
			a.menu {text-decoration: none; font-family: Verdana,helvetica; font-size: 8pt ; background:white; color: #3882c7}
			a.menu:hover {text-decoration: none; font-family: Verdana,helvetica; font-size: 8pt ; background:#83C01C; color: white}
			a.orderby {text-decoration: none; font-family: Verdana,helvetica; background: #3882c7; font-weight: normal; font-size: 8pt; color: white}
			a.orderby:hover {text-decoration: none; font-family: Verdana,helvetica; background: #3882c7; font-weight: normal; font-size: 8pt; color: #83F01C}
			th.cal {font-family: tahoma, helvetica; font-size: 8pt; background: #505050; color: white}
			th.dias {font-family: tahoma, helvetica; font-size: 7pt; background: #808080}
			a.num {color: black; font-family: tahoma, helvetica; font-size: 7pt;background: #d0d0d0;}
			a.num_sel {color: black; font-family: tahoma, helvetica; font-size: 7pt;background: #83C01C;}
			td.num {background: #d0d0d0;}
			td.num_sel {background: #83C01C;}
		[/style]

menu.bottombar_start:
[html]
	[head]
		[style]
			body
			{
			background-color: white;
			}
			table {font-size: 8pt ; color: black}
			td {font-family: Verdana,helvetica; font-size: 8pt ; color: black}
			input {font-family: Verdana,helvetica; font-size: 7pt; border: 1px solid black;}
			input.sel {font-family: Verdana,helvetica; color: #ff6500; font-weight: bold; font-size: 7pt; border: 1px solid black;}
			a.xmenu {text-decoration: none; font-family: Verdana,helvetica; font-size: 8pt ; background:white; color: #83C01C}
			a.xmenu:hover {text-decoration: none; font-family: Verdana,helvetica; font-size: 8pt ; background:#83C01C; color: white}
			a.menu {text-decoration: none; font-family: Verdana,helvetica; font-size: 8pt ; color: #3882c7}
			a.menu:hover {text-decoration: none; font-family: Verdana,helvetica; font-size: 8pt ; background:#83C01C; color:white }
		[/style]
	[/head]
	[body leftmargin=0 topmargin=0 valign='top']

menu.menu_start:
[html]
	[head]
		[style]
			body {font-family: Verdana,helvetica; font-size: 9pt ; background: white; color: black}
			table {background: red}
			select {font-family: Verdana,helvetica; font-size: 9pt}
			input {font-family: Verdana,helvetica; font-size: 9pt; }
			input.sel {font-family: Verdana,helvetica; color: blue; font-weight: bold; font-size: 9pt}
			a.menu {text-decoration: none; font-family: Verdana,helvetica; font-size: 8pt ; color: #3882c7}
			a.menu:hover {text-decoration: none; font-family: Verdana,helvetica; font-size: 8pt ; background:#83C01C; color:white}
			a {text-decoration: none; font-family: Verdana,helvetica; font-size: 8pt ; color: #202020}
			a:hover {text-decoration: none; font-family: Verdana,helvetica; font-size: 8pt ; color: #000000}
		[/style]
	[/head]
	[body leftmargin=1 topmargin=1]
